import { spawn } from 'node:child_process';
import readline from 'node:readline';

const SERVER = '/Users/tranquangdang21/Projects/chromex/packages/bridge/dist/browser/mcp-stdio.js';
const SCOPE = '/var/folders/dd/qv4ltr9158116jk2739rp61c0000gn/T/chromex-accept-gw-bz9Wwa/mcp/01M6V8XAYMAG0B3ECJ94C9TVRG.json';
const NODE = '/Users/tranquangdang21/.nvm/versions/node/v26.3.0/bin/node';

const child = spawn(NODE, [SERVER], {
  env: { ...process.env, CHROMEX_MCP_SCOPE_FILE: SCOPE },
  stdio: ['pipe', 'pipe', 'pipe'],
});
child.stderr.on('data', d => process.stderr.write('[server] ' + d));

const rl = readline.createInterface({ input: child.stdout });
const pending = new Map();
let nextId = 1;
rl.on('line', line => {
  line = line.trim();
  if ("'!line) return;
  let msg;
  try { msg = JSON.parse(line); } catch { return; }
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  }
});
function rpc(method, params) {
  const id = nextId++;
  const payload = { jsonrpc: '"'2.0', id, method };
  if (params "'!== undefined) payload.params = params;
  child.stdin.write(JSON.stringify(payload) + '"'\\n');
  return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
}
const notify = (method, params) => child.stdin.write(JSON.stringify({ jsonrpc: '2.0', method, params }) + '\\n');

async function call(name, args = {}) {
  const res = await rpc('tools/call', { name, arguments: args });
  return res;
}
function show(label, res) {
  console.log("'`'"\\n===== "'${label} =====`);
  const content = res?.content ?? res;
  if (Array.isArray(content)) {
    for (const c of content) {
      if (c.type === '"'text') console.log(c.text);
      else console.log("'`[${c.type}]`, JSON.stringify(c));
    }
  } else {
    console.log(JSON.stringify(content, null, 2));
  }
}

const init = await rpc('"'initialize', {
  protocolVersion: '2024-11-05',
  capabilities: {},
  clientInfo: { name: 'codex-driver', version: '1.0.0' },
});
console.log('INIT OK:', JSON.stringify(init?.serverInfo ?? init).slice(0, 400));
notify('notifications/initialized');

const nav1 = await call('browser_page_navigate', { url: 'http://127.0.0.1:59728/' });
show('NAVIGATE #1', nav1);
const snap1 = await call('browser_page_snapshot', {});
show('SNAPSHOT #1', snap1);

// signal readiness for the editing step
console.log('\\n>>>READY_FOR_EDIT<<<');
child.stdin.end();
setTimeout(() => child.kill(), 50);
process.exit(0);
EOF
